// Builds the currency tables from the official sources, so nobody types them by hand:
//   - which currencies exist, and how many decimals each has: ISO 4217, from SIX (the standard's maintenance agency)
//   - which currency each country uses: Unicode CLDR (unicode-org/cldr-json, published on npm as cldr-core)
// Writes apps/website/src/currency-data.ts and services/auth/currency_data.go (generated: do not edit them).
//
//   node tools/currency-data.mjs           fetch the sources and rewrite both files
//   node tools/currency-data.mjs --check   fetch them and fail when a file is out of date (run monthly by .github/workflows/currency-data.yml)

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const ISO_URL = "https://www.six-group.com/dam/download/financial-information/data-center/iso-currrency/lists/list-one.xml";
const CLDR_URL = "https://cdn.jsdelivr.net/npm/cldr-core@latest/supplemental/currencyData.json";
const OUT_TS = join(root, "landing", "site", "src", "currency-data.ts");
const OUT_GO = join(root, "services", "auth", "currency_data.go");

// Not currencies a person is charged in: precious metals, special drawing rights, test and "no currency" codes, and the funds codes.
const NOT_MONEY = new Set(["XAU", "XAG", "XPT", "XPD", "XDR", "XTS", "XXX", "XBA", "XBB", "XBC", "XBD", "XSU", "XUA", "USN", "CHE", "CHW", "CLF", "COU", "BOV", "MXV", "UYI", "UYW"]);

const get = async url => {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: ${res.status}`);
  return res;
};

// ---- ISO 4217: code -> minor-unit digits ----
const xml = await (await get(ISO_URL)).text();
const published = /Pblshd="([^"]+)"/.exec(xml)?.[1] ?? "";
const digits = {};
for (const entry of xml.split("<CcyNtry>").slice(1)) {
  const code = /<Ccy>([A-Z]{3})<\/Ccy>/.exec(entry)?.[1];
  const minor = /<CcyMnrUnts>([^<]+)<\/CcyMnrUnts>/.exec(entry)?.[1];
  if (!code || NOT_MONEY.has(code) || !/^\d$/.test(minor ?? "")) continue; // "N.A." has no minor unit
  digits[code] = Number(minor);
}
if (Object.keys(digits).length < 140) throw new Error(`ISO 4217 gave only ${Object.keys(digits).length} currencies`);

// ---- CLDR: region -> the currency in use now ----
const cldr = (await (await get(CLDR_URL)).json()).supplemental;
const today = new Date().toISOString().slice(0, 10);
const regionCurrency = {};
for (const [region, list] of Object.entries(cldr.currencyData.region)) {
  if (!/^[A-Z]{2}$/.test(region)) continue; // 001 (the world), 419 (Latin America)...
  const live = [];
  for (const item of list) {
    const [[code, info]] = Object.entries(item);
    if (info._tender === "false" || info._to || (info._from ?? "0000") > today || !(code in digits)) continue;
    live.push({ code, from: info._from ?? "0000" });
  }
  // More than one in use (Zimbabwe: its own currency and the dollar): the newest one is the one prices are set in.
  live.sort((a, b) => b.from.localeCompare(a.from));
  if (live[0]) regionCurrency[region] = live[0].code;
}
for (const code of Object.values(regionCurrency)) if (!(code in digits)) throw new Error(`${code} is used by a region but is not an ISO currency`);

const sorted = object => Object.fromEntries(Object.entries(object).sort(([a], [b]) => a.localeCompare(b)));
const sources = `ISO 4217 as published ${published} by SIX; CLDR ${cldr.version?._cldrVersion ?? ""}`.trim();

const ts = `// GENERATED by tools/currency-data.mjs from ${sources}. Do not edit: run the tool.

/** Every current ISO 4217 currency and its minor-unit digits (2 for dollars, 0 for yen, 3 for dinars). */
export const CURRENCY_DIGITS: Record<string, number> = ${JSON.stringify(sorted(digits))};

/** The currency each country uses now, by two-letter country code (CLDR). */
export const REGION_CURRENCY: Record<string, string> = ${JSON.stringify(sorted(regionCurrency))};

export const CURRENCY_DATA_SOURCE = ${JSON.stringify(sources)};
`;

const goMap = (name, object, type) => `var ${name} = map[string]${type}{\n${Object.entries(sorted(object)).map(([k, v]) => `\t${JSON.stringify(k)}: ${typeof v === "string" ? JSON.stringify(v) : v},`).join("\n")}\n}\n`;
const go = `// Code generated by tools/currency-data.mjs from ${sources}; DO NOT EDIT.

package main

// currencySource says where the tables below came from.
const currencySource = ${JSON.stringify(sources)}

// isoMinorUnits is every current ISO 4217 currency and how many decimals its minor unit has.
${goMap("isoMinorUnits", digits, "int")}
// regionCurrency is the currency each country uses now, by two-letter country code.
${goMap("regionCurrency", regionCurrency, "string")}`;

const check = process.argv.includes("--check");
let stale = 0;
for (const [file, text] of [[OUT_TS, ts], [OUT_GO, go]]) {
  let current = "";
  try { current = readFileSync(file, "utf8").replace(/\r\n/g, "\n"); } catch { /* not there yet */ }
  if (current === text) continue;
  if (check) { console.error(`${file} is out of date: run node tools/currency-data.mjs`); stale++; } else { writeFileSync(file, text); console.log(`wrote ${file}`); }
}
if (check && stale) process.exit(1);
console.log(`${Object.keys(digits).length} currencies, ${Object.keys(regionCurrency).length} countries (${sources})`);
